struct WgPieceProcessorRule {
  uint8_t input_kind; // 0 block, 1 random block, 2 tag, 3 blockstate
  uint16_t input;
  uint16_t output_state;
  float probability;
  uint8_t location_kind; // 0 always, 1 block match
  uint16_t location;
  // `append_loot`: the table written onto the rule's output block, or
  // 0xFFFF for a plain `passthrough`/`clear` rule.
  uint16_t loot_table;
  // `tag_match`: the resolved member blocks. Empty for other kinds.
  uint32_t input_block_offset;
  uint16_t input_block_count;
};
struct WgPieceCappedPass {
  uint32_t rule_offset;
  uint16_t rule_count;
  uint16_t limit_min; // constant providers in this pack
  uint16_t limit_max;
};
struct WgPieceProcessorList {
  uint32_t rule_offset;
  uint16_t rule_count;
  // `BlockRotProcessor`'s integrity: a block is dropped when the
  // per-position draw is above this. 1.0 when the list has none.
  float block_rot_integrity;
  // `BlockRotProcessor.rottable_blocks`: the state must be one of these
  // for the draw to apply; empty means every state.
  uint32_t rot_block_offset;
  uint16_t rot_block_count;
  // `ProtectedBlockProcessor`: a write is skipped when the world cell
  // already holds one of these blocks.
  uint32_t protected_block_offset;
  uint16_t protected_block_count;
  // `CappedProcessor` passes, in list order. Each shuffles the whole
  // piece's surviving blocks and applies its delegate to at most
  // `limit` of them; empty for a list without one.
  uint32_t capped_offset;
  uint16_t capped_count;
};
