struct WgJigsawConfig {
  const char* name;
  uint16_t start_pool;
  uint8_t max_depth; // the structure JSON's `size`
  // `start_height`: 0 absolute (min == max), 1 uniform [min, max].
  uint8_t start_height_kind;
  int16_t start_height_min;
  int16_t start_height_max;
  uint8_t project_heightmap; // 1 = WORLD_SURFACE_WG
  uint8_t use_expansion_hack;
  uint16_t max_distance; // horizontal and vertical
  // `start_jigsaw_name` as a `kWgJigsawStringTable` index, or 0xFFFF.
  uint16_t start_jigsaw;
};
